import AppKit

extension VideoPane {
    // MARK: Speed

    /// Speed is a clip-level op, not a patch: `set_speed` takes one clip and
    /// re-times its actions (§6), so the selection becomes one op each and the
    /// whole batch is a single undo step. The one exception is Rate (and the
    /// section's Reset) with an action selected, which writes that action's
    /// `end.speed`, a speed ramp (spec §11 SR-21 (a)); Keep pitch and Fit to
    /// stay the clip's.
    ///
    /// Reverse used to sit here, next to Rate, because both re-time the same
    /// source. It now sits in the Clip tab's Timing section with In, Out and
    /// Duration, which is what the redesign asks for and reads better anyway:
    /// Rate is how fast, Reverse is which way, and the duration readout the
    /// two of them share belongs with the edges it is measured between.
    func speedSection() -> InspectorSection {
        let binding = self.binding
        return InspectorSection(
            id: "video.speed", title: "Speed",
            summary: { String(format: "%.2f×", Self.rateRead(binding)) },
            reset: { binding.apply("Set Speed", Self.rateOps(binding, rate: 1)) },
            differs: { Self.rateRead(binding) != 1 },
            defaultExpanded: false,
            rows: [
                inspectorValueRow(
                    "Rate", binding, name: "Set Speed", unit: "×", decimals: 2,
                    min: ReelSpeed.limits.min, max: ReelSpeed.limits.max,
                    quick: [0.5, 1, 2, 4], slider: false,
                    read: { Self.rateRead(binding) },
                    ops: { Self.rateOps(binding, rate: $0) },
                    mixed: { binding.mixed { $0.speed } }, resets: false),
                inspectorCheckRow(
                    "Keep pitch", binding, name: "Keep Pitch",
                    read: { binding.audioProps.keepPitch },
                    ops: { value in
                        Self.speedOps(binding, Self.baseRate(binding), keepPitch: value)
                    },
                    mixed: { binding.mixedAudio { $0.keepPitch } }),
                fitRow(),
                InspectorNoteLabel(wraps: true) {
                    Self.silentAudioNote(
                        for: binding.clips, in: binding.snapshot, limits: ReelSpeed.limits)
                },
            ])
    }

    /// The first selected clip's BASE rate, ×1 when it is not positive: what
    /// Keep pitch re-sends with its switch, so a click inside an action never
    /// writes the action's rate onto the clip (spec §11 SR-21 (a)).
    static func baseRate(_ binding: InspectorBinding) -> Double {
        let value = binding.primary?.speed ?? 1
        return value > 0 ? value : 1
    }

    /// What Rate shows: the first selected clip's `speed(_:)` in the
    /// binding's mode — the selected action's end rate, else the core's rate
    /// in force there, else the base (spec §11 SR-21 (b)); ×1 when it is not
    /// positive.
    static func rateRead(_ binding: InspectorBinding) -> Double {
        let value = binding.primary.map { binding.speed($0) } ?? 1
        return value > 0 ? value : 1
    }

    /// Rate's write (spec §11 SR-21 (a)): with an action selected on the one
    /// selected media clip, that action's `end.speed` — one `set_action_end`;
    /// otherwise one `set_speed` per selected media clip, as before.
    static func rateOps(_ binding: InspectorBinding, rate: Double) -> [ReelOp] {
        if binding.isSingle, let clip = binding.primary, clip.source.hasSourceBound,
            let action = binding.action(clip)
        {
            return [.setActionEnd(clip: clip.id, action: action.id, patch: ActionPatch(speed: rate))]
        }
        return speedOps(binding, rate, keepPitch: nil)
    }

    /// One `set_speed` per selected media clip: the clip's own rate, whatever
    /// action is selected.
    private static func speedOps(
        _ binding: InspectorBinding, _ next: Double, keepPitch: Bool?
    ) -> [ReelOp] {
        binding.clips.filter { $0.source.hasSourceBound }
            .map { .setSpeed(clip: $0.id, rate: next, keepPitch: keepPitch) }
    }

    /// "Fit to": type a length and the rate changes so each selected media
    /// clip plays in it (`set_speed`'s duration arm, spec §11 #190).
    ///
    /// **It binds by the ids captured here**, `ClipPane+Timing.swift`'s rule:
    /// the field commits on blur, and a blur the rebuild causes would
    /// otherwise write to whichever clip was clicked next.
    private func fitRow() -> NSView {
        let binding = self.binding
        let ids = binding.clips.filter { $0.source.hasSourceBound }.map(\.id)
        let field = InspectorTimecodeField(
            read: { ids.first.flatMap { binding.snapshot.clip($0) }?.duration ?? 0 },
            write: { binding.apply("Fit to Duration", Self.fitOps(ids, duration: $0)) },
            fps: { binding.canvas.fps }, frames: { binding.canvas.timecodeFrames },
            onEdit: { binding.edited() })
        field.toolTip = "Type a length: the rate changes so the clip plays in it"
        // Its writes are the clip's (`set_speed`), so the row is ⊘ while an
        // action is selected (spec §11 SR-21 (a), CI-7).
        let length = ids.first.flatMap { binding.snapshot.clip($0) }?.duration ?? 0
        return inspectorRow(
            "Fit to", [field],
            mixed: { binding.mixed(ids.compactMap { binding.snapshot.clip($0) }) { $0.duration } },
            binding: binding, writes: Self.fitOps(ids, duration: length))
    }

    /// The Speed section's note when a selected clip's audio has been left out
    /// of the mix: the first media clip with sound, its audio enabled, whose
    /// speed is above the audio ceiling, in either pitch mode (spec §11 #190).
    /// A clip's speed here is the greatest rate it names (`peakSpeed`, spec
    /// §11 SR-19 (d), SR-21 (e)), the figure the plan leaves its audio out by.
    /// Nil otherwise.
    static func silentAudioNote(
        for clips: [ClipSnapshot], in snapshot: ProjectSnapshot, limits: SpeedLimits
    ) -> String? {
        for clip in clips where clip.source.hasSourceBound && clip.enabled.audio {
            guard snapshot.media(for: clip)?.hasAudio == true else { continue }
            if SpeedAudioDrop.peakSpeed(of: clip, limits: limits) > limits.audioMax {
                return "Audio is silent above ×" + String(format: "%g", limits.audioMax)
            }
        }
        return nil
    }

    /// One `set_speed` duration arm per clip, so a multi-clip Fit is one undo
    /// step.
    static func fitOps(_ clips: [UInt32], duration: Ticks) -> [ReelOp] {
        clips.map { .setSpeed(clip: $0, duration: duration) }
    }
}
import AppKit

/// The rate controls the Speed and Speed Ramp sheets share: the field, the
/// presets pull-down, the row they sit on and the range footnote (#359).
/// The rates themselves are `SpeedSheetController`'s statics — `rateRange`,
/// `presets` and `title(for:)` — which both sheets and the probes read.
enum SpeedRateControls {
    /// The rate field: a decimal formatter holding §6's clamp, so the field
    /// refuses a rate outside it rather than the core silently clamping a
    /// number the user typed.
    static func styleRateField(
        _ field: NSTextField, initial: Double, delegate: NSTextFieldDelegate
    ) {
        let formatter = NumberFormatter()
        formatter.numberStyle = .decimal
        formatter.allowsFloats = true
        formatter.minimumFractionDigits = 0
        formatter.maximumFractionDigits = 3
        formatter.minimum = NSNumber(value: SpeedSheetController.rateRange.lowerBound)
        formatter.maximum = NSNumber(value: SpeedSheetController.rateRange.upperBound)
        field.formatter = formatter
        field.delegate = delegate
        field.alignment = .right
        field.doubleValue = initial
        field.widthAnchor.constraint(equalToConstant: 80).isActive = true
        DSField.style(field)
    }

    /// The presets pull-down. A pull-down's first item is its title and is
    /// never chosen, so it carries no rate; every other item carries its
    /// rate as an `NSNumber`.
    static func fillPresets(_ popup: NSPopUpButton, target: AnyObject, action: Selector) {
        popup.menu?.addItem(item("Presets", nil))
        for preset in SpeedSheetController.presets {
            popup.menu?.addItem(
                item(SpeedSheetController.title(for: preset), NSNumber(value: preset)))
        }
        popup.font = DS.sans(13)
        popup.target = target
        popup.action = action
        popup.widthAnchor.constraint(equalToConstant: 96).isActive = true
    }

    /// The rate the chosen preset carries; nil for the pull-down's face.
    static func preset(of popup: NSPopUpButton) -> Double? {
        (popup.selectedItem?.representedObject as? NSNumber)?.doubleValue
    }

    /// The field, its "×" and the presets, on one grid row.
    static func rateRow(field: NSTextField, presets: NSPopUpButton) -> NSStackView {
        sheetRow([field, sheetUnitLabel("×"), presets])
    }

    /// The rate range, "×min – ×max": the button row's footnote.
    static func rangeFootnote() -> NSTextField {
        let range = SpeedSheetController.rateRange
        return sheetFootnote(String(format: "×%g – ×%g", range.lowerBound, range.upperBound))
    }

    /// `rate` held inside §6's clamp.
    static func clamp(_ rate: Double) -> Double {
        let range = SpeedSheetController.rateRange
        return min(max(rate, range.lowerBound), range.upperBound)
    }

    private static func item(_ title: String, _ value: Any?) -> NSMenuItem {
        let item = NSMenuItem(title: title, action: nil, keyEquivalent: "")
        item.representedObject = value
        return item
    }
}

import AppKit

/// Clip ▸ Speed…: the playback rate for the selected clips, whether pitch is
/// preserved, and the length that results (spec §6's `set_speed`).
///
/// Only `media` clips are offered. `set_speed` is an ERROR, not a refusal, on
/// any other source kind (§6), so a still or a text clip in the selection is
/// filtered out here rather than being sent and coming back as an alert —
/// `EditorViewController+Export.swift` refuses to open the sheet at all when
/// nothing in the selection qualifies.
///
/// **The duration readout is the CORE's answer, not a copy of it** (spec §11,
/// D4-6). It applies the sheet's own ops to the immutable handle and reads the
/// durations back: an edit is pure (§5.5), so asking costs a discarded handle
/// and needs no new export. A quotient in Swift could not say what `set_speed`
/// really writes — the duration is snapped to the nearest frame and then held
/// to what the FILE holds at the new rate (D4-3), and a clip slowed into its
/// neighbour is either APPLIED at its full new length, the neighbour gaining a
/// minted cross dissolve, or REFUSED by the overlap rule and left as it was.
/// `applying` runs past a refusal, so a mixed selection reads the applied
/// clips' new lengths beside the refused clips' old ones, which is exactly
/// what Apply will write.
final class SpeedSheetController: NSViewController, NSTextFieldDelegate {
    /// Weak, like every sheet's back-reference: the document must be free to
    /// close even with a dialog mid-air.
    private weak var document: ProjectDocument?
    /// Clip ids, not snapshots: a `ClipSnapshot` captured at open time would
    /// be a stale copy of a value the document replaces wholesale on every
    /// edit (the inspector rule, and the same reasoning applies here).
    private let clips: [UInt32]

    /// The rate the selection started at — 1 when the clips disagree — so
    /// "changed nothing" can be told from "set them all to what one of them
    /// already was".
    private let originalRate: Double
    private let originalKeepPitch: Bool
    /// True when the selection did not agree on a rate. Then ×1 IS a change —
    /// it normalises them — even though it equals `originalRate`.
    private let ratesDiffer: Bool

    private let rateField = NSTextField(string: "")
    private let presetPopup = NSPopUpButton(frame: .zero, pullsDown: true)
    private let pitchCheckbox = NSButton(
        checkboxWithTitle: "Preserve pitch", target: nil, action: nil)
    private let durationLabel = NSTextField(wrappingLabelWithString: "")

    /// §6 clamps the rate to the core's `ReelSpeed.limits`; the field refuses
    /// outside them rather than letting the core silently clamp a number the
    /// user typed.
    static let rateRange = ReelSpeed.limits.range
    /// The rates the pull-down offers: the common editing rates, then ×10 and ×100
    /// for a long recording (spec §11 #190).
    static let presets: [Double] = [0.25, 0.5, 1, 1.5, 2, 4, 10, 100]

    init(document: ProjectDocument, clips: [UInt32]) {
        self.document = document
        self.clips = clips
        // The EDITED project: this sheet is opened on the SELECTION, and with
        // a nest open the selection is the nest's clips (road map 2's phase
        // 9). At the top level it is `document.project` as before.
        let snapshot = document.editedProject.snapshot
        let speeds = clips.compactMap { snapshot.clip($0)?.speed }
        let first = speeds.first ?? 1
        let uniform = speeds.allSatisfy { $0 == first } && first > 0
        self.ratesDiffer = !uniform
        self.originalRate = uniform ? first : 1
        self.originalKeepPitch =
            clips.compactMap { snapshot.clip($0)?.audioProps.keepPitch }.first ?? true
        super.init(nibName: nil, bundle: nil)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("SpeedSheetController does not support NSCoder")
    }

    // MARK: - View

    override func loadView() {
        SpeedRateControls.styleRateField(rateField, initial: originalRate, delegate: self)
        SpeedRateControls.fillPresets(
            presetPopup, target: self, action: #selector(presetChosen(_:)))

        pitchCheckbox.state = originalKeepPitch ? .on : .off
        pitchCheckbox.font = DS.sans(13)
        pitchCheckbox.target = self
        pitchCheckbox.action = #selector(pitchChanged(_:))

        durationLabel.font = DS.mono(11)
        durationLabel.textColor = DS.textMuted
        durationLabel.preferredMaxLayoutWidth = sheetWidth - sheetInset * 2

        let rateRow = SpeedRateControls.rateRow(field: rateField, presets: presetPopup)

        let grid = makeSheetGrid([
            [fieldLabel("Rate:"), rateRow],
            [NSGridCell.emptyContentView, pitchCheckbox],
        ])

        let content = sheetColumn([grid, durationLabel])

        let cancelButton = sheetCancelButton(target: self, action: #selector(cancelClicked(_:)))
        let applyButton = sheetApplyButton(target: self, action: #selector(applyClicked(_:)))
        view = makeSheetView(
            title: "Speed",
            hint: "Faster clips can leave gaps; slower clips can overlap. Later clips stay in "
                + "place. A clip an allowed overlap reaches gains a transition, named below. "
                + "If an overlap is not allowed, that clip stays unchanged; other selected "
                + "clips can still change.",
            content: content,
            buttonRow: makeButtonRow(
                cancel: cancelButton, apply: applyButton,
                leading: [SpeedRateControls.rangeFootnote()]))
        syncReadout()
    }

    static func title(for rate: Double) -> String {
        String(format: rate < 1 ? "%.2f×" : "%g×", rate)
    }

    // MARK: - Values

    /// The rate the controls describe, always inside §6's clamp.
    private var rate: Double {
        SpeedRateControls.clamp(rateField.doubleValue)
    }

    private var keepPitch: Bool { pitchCheckbox.state == .on }

    /// The ops Apply sends — one `set_speed` per clip, in the selection's own
    /// order — so what the readout asks about and what Apply writes are one
    /// list and cannot drift. `applyClicked` calls it.
    static func ops(for clips: [UInt32], rate: Double, keepPitch: Bool) -> [ReelOp] {
        clips.map { .setSpeed(clip: $0, rate: rate, keepPitch: keepPitch) }
    }

    /// A clip whose transition a trial makes play (#109), or makes longer or
    /// shorter (#184), and that transition's length after the trial.
    struct TransitionChange: Equatable {
        enum Change: Equatable { case gains, grows, shrinks }
        let clip: UInt32
        let kind: TransitionKind
        let change: Change
        /// The overlap with its predecessor after the trial.
        let duration: Ticks
    }

    /// The project once the sheet's ops have run — the ONE `applying` every
    /// line of the readout is read off. A refusal still answers the project
    /// with the refused clips as they were.
    static func trial(
        of clips: [UInt32], rate: Double, keepPitch: Bool, in project: ReelProject
    ) -> ProjectSnapshot {
        let ops = Self.ops(for: clips, rate: rate, keepPitch: keepPitch)
        return ((try? project.applying(ops)).project ?? project).snapshot
    }

    /// What the selection measures now, and what it measures once those ops
    /// have run — the two numbers the readout prints, both read off a project.
    ///
    /// `after` is summed from the handle the ops make, not from arithmetic
    /// here, which is the whole of the type doc's claim. A clip the core
    /// refused is absent from nothing — it is still in the applied snapshot,
    /// at the length it had — so a refusal reads as "no change" for that clip
    /// and the rest of the selection still counts.
    static func lengths(
        of clips: [UInt32], rate: Double, keepPitch: Bool, in project: ReelProject
    ) -> (before: Ticks, after: Ticks) {
        lengths(
            of: clips, before: project.snapshot,
            after: trial(of: clips, rate: rate, keepPitch: keepPitch, in: project))
    }

    static func lengths(
        of clips: [UInt32], before snapshot: ProjectSnapshot, after applied: ProjectSnapshot
    ) -> (before: Ticks, after: Ticks) {
        var before: Ticks = 0
        var after: Ticks = 0
        for id in clips {
            guard let clip = snapshot.clip(id), clip.speed > 0 else { continue }
            before += clip.duration
            after += applied.clip(id)?.duration ?? clip.duration
        }
        return (before, after)
    }

    /// Every clip, on a track holding one of `clips`, whose transition plays
    /// in `after` and either did not in `before` (`.gains` — a minted cross
    /// dissolve, or a transition set earlier that an overlap now reaches) or
    /// did at a smaller or larger overlap (`.grows`, `.shrinks`). A transition
    /// plays when the clip has one and overlaps its predecessor
    /// (`VideoPane.overlap(before:)`'s idiom). One that plays in both at the
    /// same overlap is absent. Ordered by start, then id.
    static func transitionChanges(
        of clips: [UInt32], before: ProjectSnapshot, after: ProjectSnapshot
    ) -> [TransitionChange] {
        func overlap(_ id: UInt32, in snapshot: ProjectSnapshot) -> Ticks {
            guard let clip = snapshot.clip(id) else { return 0 }
            let earlier = snapshot.clips(onTrack: clip.track).filter { $0.start < clip.start }
            guard let previous = earlier.last else { return 0 }
            return previous.end - clip.start
        }
        func effective(_ id: UInt32, in snapshot: ProjectSnapshot) -> Bool {
            snapshot.clip(id)?.transitionIn != nil && overlap(id, in: snapshot) > 0
        }
        let tracks = Set(clips.compactMap { before.clip($0)?.track })
        var changes: [(start: Ticks, change: TransitionChange)] = []
        for clip in after.clips where tracks.contains(clip.track) {
            let id = clip.id
            let had = effective(id, in: before)
            guard effective(id, in: after), let kind = clip.transitionIn?.kind else { continue }
            let now = overlap(id, in: after)
            let was = overlap(id, in: before)
            guard !had || now != was else { continue }
            let change: TransitionChange.Change = !had ? .gains : now > was ? .grows : .shrinks
            changes.append(
                (clip.start, TransitionChange(clip: id, kind: kind, change: change, duration: now)))
        }
        return changes.sorted { ($0.start, $0.change.clip) < ($1.start, $1.change.clip) }
            .map(\.change)
    }

    /// "clip 7 gains a 0.67 s cross dissolve", "clip 7's cross dissolve grows
    /// to 1.50 s", "clip 7's cross dissolve shrinks to 0.67 s".
    static func changeLine(_ change: TransitionChange) -> String {
        let seconds = String(format: "%.2f", ReelTime.seconds(change.duration))
        let kind = change.kind.displayName.lowercased()
        switch change.change {
        case .gains: return "clip \(change.clip) gains a \(seconds) s \(kind)"
        case .grows: return "clip \(change.clip)'s \(kind) grows to \(seconds) s"
        case .shrinks: return "clip \(change.clip)'s \(kind) shrinks to \(seconds) s"
        }
    }

    /// The readout's last line when a selected clip ramps its speed: Apply
    /// sets the base rate and scales the ramp with it (rule L, spec §11
    /// SR-19 (a), SR-21 (f)).
    static let rampLine =
        "Each speed ramp keeps its shape: the rates it names scale with the base rate."

    /// "3 clips · 00:00:12:00 → 00:00:06:00", then one `changeLine` per clip
    /// whose transition the trial makes play, grow or shrink — every line
    /// read off one trial handle — then `rampLine` when a selected clip is
    /// ramped (the core's `sourceMap`).
    static func readout(
        of clips: [UInt32], rate: Double, keepPitch: Bool, in project: ReelProject
    ) -> String {
        let before = project.snapshot
        let after = trial(of: clips, rate: rate, keepPitch: keepPitch, in: project)
        let (from, to) = lengths(of: clips, before: before, after: after)
        let fps = before.canvas.fps
        let count = clips.count == 1 ? "1 clip" : "\(clips.count) clips"
        let summary =
            count + " · " + ReelTime.format(from, fps: fps, frames: true) + " → "
            + ReelTime.format(to, fps: fps, frames: true)
        let changes = transitionChanges(of: clips, before: before, after: after)
        let ramp = clips.contains { project.sourceMap($0)?.ramped == true } ? [rampLine] : []
        return ([summary] + changes.map(changeLine) + ramp).joined(separator: "\n")
    }

    private func syncReadout() {
        guard let project = document?.editedProject else {
            durationLabel.stringValue = ""
            return
        }
        durationLabel.stringValue = Self.readout(
            of: clips, rate: rate, keepPitch: keepPitch, in: project)
    }

    // MARK: - Controls

    @objc private func presetChosen(_ sender: Any?) {
        guard let preset = SpeedRateControls.preset(of: presetPopup) else { return }
        rateField.doubleValue = preset
        // The pull-down always shows its own title, so put it back.
        presetPopup.selectItem(at: 0)
        syncReadout()
    }

    @objc private func pitchChanged(_ sender: Any?) {
        syncReadout()
    }

    func controlTextDidEndEditing(_ obj: Notification) {
        rateField.doubleValue = rate
        syncReadout()
    }

    // MARK: - Commit

    @objc private func cancelClicked(_ sender: Any?) {
        dismiss(self)
    }

    /// One `set_speed` per clip, committed as ONE undo step. A rate that is
    /// already what every clip has is not an edit — the core would return
    /// identity and `applyEdit` would beep at a dialog the user just
    /// confirmed, which reads as a refusal rather than as "nothing to do".
    ///
    /// A rate that takes a clip with sound above the audio ceiling asks first
    /// (`SpeedAudioDrop`, #212), on this sheet's own window: Set Speed closes
    /// the sheet and applies, Cancel leaves the sheet up with nothing applied.
    @objc private func applyClicked(_ sender: Any?) {
        let rate = self.rate
        let keepPitch = self.keepPitch
        guard ratesDiffer || rate != originalRate || keepPitch != originalKeepPitch else {
            dismiss(self)
            return
        }
        guard let document = self.document, !clips.isEmpty else {
            dismiss(self)
            return
        }
        SpeedAudioDrop.commit(
            "Set Speed", Self.ops(for: clips, rate: rate, keepPitch: keepPitch), to: document,
            asking: view.window, before: { [weak self] in if let self { self.dismiss(self) } })
    }
}
import AppKit

/// Clip ▸ Retime Range… (road map "creator-jobs" CU9a, spec §11 CU-90 (d)):
/// the In–Out range played faster or slower on every unlocked track, and
/// everything after it moved to stay in step — one `retime_range`, one undo
/// step "Retime Range".
///
/// Rate starts at ×2 with the Speed sheet's field, presets and footnote
/// (`SpeedRateControls`); Preserve pitch starts at the Keep pitch of the first
/// media clip on an unlocked track that overlaps the range, on when there is
/// none. Apply at ×1 only closes the sheet. Otherwise it commits through
/// `SpeedAudioDrop.commit`, always sending `keep_pitch`, so a rate that takes
/// a clip with sound above the audio ceiling asks first, on this sheet's
/// window: Set Speed closes the sheet and applies, Cancel leaves it up with
/// nothing applied. What the core refuses comes back as `applyEdit`'s strip.
///
/// **The dev accept** (`-RCDevRetimeAccept YES`, dev tools only): the sheet
/// presses its own Apply once it is up, so a proof can drive the menu item to
/// its edit (AU-128's precedent).
final class RetimeSheetController: NSViewController, NSTextFieldDelegate {
    /// The dev-only launch default that presses Apply.
    static let devAcceptKey = "RCDevRetimeAccept"
    /// The rate the sheet opens at.
    static let initialRate: Double = 2

    /// Weak, like every sheet's back-reference: the document must be free to
    /// close even with a dialog mid-air.
    private weak var document: ProjectDocument?
    private let range: (from: Ticks, to: Ticks)
    private let originalKeepPitch: Bool

    private let rateField = NSTextField(string: "")
    private let presetPopup = NSPopUpButton(frame: .zero, pullsDown: true)
    private let pitchCheckbox = NSButton(
        checkboxWithTitle: "Preserve pitch", target: nil, action: nil)

    init(document: ProjectDocument, range: (from: Ticks, to: Ticks)) {
        self.document = document
        self.range = range
        // The EDITED project: inside a nest the range is the nest's.
        self.originalKeepPitch = Self.initialKeepPitch(
            in: document.editedProject.snapshot, from: range.from, to: range.to)
        super.init(nibName: nil, bundle: nil)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("RetimeSheetController does not support NSCoder")
    }

    // MARK: - View

    override func loadView() {
        SpeedRateControls.styleRateField(rateField, initial: Self.initialRate, delegate: self)
        SpeedRateControls.fillPresets(
            presetPopup, target: self, action: #selector(presetChosen(_:)))

        pitchCheckbox.state = originalKeepPitch ? .on : .off
        pitchCheckbox.font = DS.sans(13)

        let grid = makeSheetGrid([
            [fieldLabel("Rate:"), SpeedRateControls.rateRow(field: rateField, presets: presetPopup)],
            [NSGridCell.emptyContentView, pitchCheckbox],
        ])

        let cancelButton = sheetCancelButton(target: self, action: #selector(cancelClicked(_:)))
        let applyButton = sheetApplyButton(target: self, action: #selector(applyClicked(_:)))
        view = makeSheetView(
            title: "Retime Range",
            hint: "Every unlocked track between In and Out plays faster or slower, and "
                + "everything after Out moves to stay in step. One undo step.",
            content: sheetColumn([grid]),
            buttonRow: makeButtonRow(
                cancel: cancelButton, apply: applyButton,
                leading: [SpeedRateControls.rangeFootnote()]))
    }

    override func viewDidAppear() {
        super.viewDidAppear()
        #if FRAMEJOB_DEV_TOOLS
        if UserDefaults.standard.bool(forKey: Self.devAcceptKey) {
            DispatchQueue.main.async { [weak self] in self?.applyClicked(nil) }
        }
        #endif
    }

    // MARK: - Values

    /// The ops Apply sends: one `retime_range` over the range.
    static func ops(from: Ticks, to: Ticks, rate: Double, keepPitch: Bool) -> [ReelOp] {
        [.retimeRange(from: from, to: to, rate: rate, keepPitch: keepPitch)]
    }

    /// Preserve pitch's first state: the Keep pitch of the first media clip,
    /// in snapshot order, on an unlocked track and overlapping `[from, to)`;
    /// on when there is none.
    static func initialKeepPitch(in snapshot: ProjectSnapshot, from: Ticks, to: Ticks) -> Bool {
        let unlocked = Set(snapshot.tracks.filter { !$0.locked }.map(\.id))
        let first = snapshot.clips.first { clip in
            guard case .media = clip.source else { return false }
            return unlocked.contains(clip.track) && clip.start < to && clip.end > from
        }
        return first?.audioProps.keepPitch ?? true
    }

    /// The rate the controls describe, always inside the core's clamp.
    private var rate: Double {
        SpeedRateControls.clamp(rateField.doubleValue)
    }

    private var keepPitch: Bool { pitchCheckbox.state == .on }

    // MARK: - Controls

    @objc private func presetChosen(_ sender: Any?) {
        guard let preset = SpeedRateControls.preset(of: presetPopup) else { return }
        rateField.doubleValue = preset
        // The pull-down always shows its own title, so put it back.
        presetPopup.selectItem(at: 0)
    }

    func controlTextDidEndEditing(_ obj: Notification) {
        rateField.doubleValue = rate
    }

    // MARK: - Commit

    @objc private func cancelClicked(_ sender: Any?) {
        dismiss(self)
    }

    /// ×1 is no edit: the core answers an identity and `applyEdit` would beep
    /// at a dialog the person just confirmed, so the sheet only closes.
    @objc private func applyClicked(_ sender: Any?) {
        let rate = self.rate
        guard rate != 1, let document = self.document else {
            dismiss(self)
            return
        }
        SpeedAudioDrop.commit(
            "Retime Range",
            Self.ops(from: range.from, to: range.to, rate: rate, keepPitch: keepPitch),
            to: document, asking: view.window,
            before: { [weak self] in if let self { self.dismiss(self) } })
    }
}

//! Clip timing operations: trims and rate changes with source and action bounds.

use crate::edit_clip::clip_end;
use crate::edit_speed_profile::profile_factors;
use crate::model::{Clip, Project, Source};
use crate::model_words::rebase_words;
use crate::outcome::Outcome;
use crate::recipe_graphic::graphic_advanced;
use crate::source_window::source_advanced_through;
use crate::time::Ticks;

/// Speed range, `SPEED_MIN`–`SPEED_MAX` (spec §4.3, §11 #190). Three
/// readers: `set_speed` clamps to it, `rate_stretch` stays inside it, and
/// `Project::validate` refuses a clip outside it (spec §11 R6-10, amended by
/// #41). The app reads it through `rc_speed_limits` and never retypes it.
pub(crate) const SPEED_MIN: f64 = 0.1;
pub(crate) const SPEED_MAX: f64 = 1000.0;

/// The fastest a clip's audio still plays, in both pitch modes (spec §11
/// #190, the owner's decision of 2026-10-01). Above it the plan leaves the
/// clip's audio segment out (`evaluate.rs`); the video still runs to
/// `SPEED_MAX`. Chosen with a margin below a measured stall: an h264
/// export's loudness pass never finishes for a keep-pitch clip that starts
/// its audio track from ×15, nor in either mode from about ×20; ×12 and ×14
/// finish. B52a's mixer limits (×24 spectral, ×32 varispeed) hold only for
/// the mixer and an audio-only export, and are not the product's ceiling.
pub(crate) const AUDIO_SPEED_MAX: f64 = 12.0;

/// Every number about speed, as `rc_speed_limits` publishes it:
/// `{"min":0.1,"max":1000.0,"audio_max":12.0}`.
pub(crate) fn speed_limits() -> serde_json::Value {
    serde_json::json!({
        "min": SPEED_MIN,
        "max": SPEED_MAX,
        "audio_max": AUDIO_SPEED_MAX,
    })
}

impl Project {
    /// Moves the clip's start edge to `to`, advancing the source in point
    /// by `(to - start) × speed` so the frame under the edge does not move
    /// (spec §6).
    ///
    /// Clamped to the source bound — `to ≥ start - in/speed` snapped UP to
    /// a frame, `source_window.rs`'s `earliest_start_on_grid` (spec §11,
    /// D4-5) — and to leaving at least one frame of clip. Actions are
    /// deliberately left alone: clip-relative, rebasing would drop or bake
    /// whatever fell off the front, which is lossy and makes trimming back
    /// out not an identity. On a RAMPED clip the actions keep their clip
    /// time too, so `in` advances by round(S(Δ)) moving in and at the base
    /// rate moving out, and the edge is held where the clip still fits its
    /// media (`front_edge_held`, spec §11 SR-18 (c)): what plays after the
    /// new start can change. `text.words` are the opposite, on purpose
    /// (spec §11, W-3): a word is anchored to speech that stays where it is
    /// on the timeline, so every word is rebased by the trim's delta and a
    /// word trimmed off the front keeps its (negative) time. A graphic's
    /// `in` advances by the same delta (road map 10's G-9), with no speed
    /// and no head bound, never below 0.
    ///
    /// Without `alone`, a linked partner whose start is this clip's is
    /// trimmed to the same `to` after it, by its own clamps; with it, the
    /// clip moves alone — the J-cut (spec §11 AU-93, `carried_edge`).
    pub fn trim_start(&self, clip: u32, to: Ticks, alone: bool) -> Result<Outcome, String> {
        self.carried_edge(
            clip,
            alone,
            |target, partner| partner.start == target.start,
            |project, id| project.trim_start_one(id, to),
        )
    }

    fn trim_start_one(&self, clip: u32, to: Ticks) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        let end = clip_end(&target);
        let latest = end.saturating_sub(self.frame());
        let mut to = self.snapped(to).min(latest).max(0);

        if let Some(earliest) = self.earliest_start_on_grid(&target) {
            to = to.max(earliest.max(0));
        }
        // A ramped clip's edge is held where the clip still fits its media
        // (spec §11 SR-18 (c)); a constant clip's is `to` as clamped.
        let to = self.front_edge_held(&target, to);
        // The two clamps can cross when the source has almost nothing left
        // in front: then there is no legal new start, so nothing happens.
        if to > latest || to == target.start {
            return Ok(Outcome::Identity);
        }

        let delta = to.saturating_sub(target.start);
        let mut moved = target.clone();
        moved.source = source_advanced_through(&target, delta);
        moved.start = to;
        moved.duration = end.saturating_sub(to);
        moved.graphic = graphic_advanced(target.graphic.as_ref(), delta);
        if let Some(text) = moved.text.as_mut() {
            rebase_words(text, delta);
        }
        self.commit_replacements(vec![moved])
    }

    /// Moves the clip's end edge to `to`, clamped to the source's remaining
    /// length (media sources) and to at least one frame of clip (spec §6).
    /// The source in point and the actions are untouched. The bound is
    /// `source_window.rs`'s `latest_end_on_grid`, measured at this clip's
    /// OWN start: the last frame at or before the end of the file, and
    /// never the one past it (spec §11, #22 and D4-2). A ramped clip's bound
    /// reads its map on past the end (S∞, spec §11 SR-18 (a)). A graphic's
    /// `length` is untouched: null follows the new end, a number stays (G-9).
    /// `alone` is `trim_start`'s: without it a linked partner ending where
    /// this clip ends follows; with it, the L-cut (spec §11 AU-93).
    pub fn trim_end(&self, clip: u32, to: Ticks, alone: bool) -> Result<Outcome, String> {
        self.carried_edge(
            clip,
            alone,
            |target, partner| clip_end(partner) == clip_end(target),
            |project, id| project.trim_end_one(id, to),
        )
    }

    fn trim_end_one(&self, clip: u32, to: Ticks) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        let earliest = target.start.saturating_add(self.frame());
        let mut to = self.snapped(to).max(earliest);
        if let Some(latest) = self.latest_end_on_grid(&target) {
            to = to.min(latest);
        }
        if to < earliest || to == clip_end(&target) {
            return Ok(Outcome::Identity);
        }

        let mut moved = target.clone();
        moved.duration = to.saturating_sub(target.start);
        self.commit_replacements(vec![moved])
    }

    /// Drags the clip's end edge to `to_end` by changing its SPEED, not the
    /// source range it shows: `speed = source_len / (to_end - start)`
    /// (spec §6). Media sources only.
    ///
    /// An IDENTITY when the new length is under a frame or the resulting rate
    /// falls outside `SPEED_MIN`–`SPEED_MAX`; refused only when the placement
    /// breaks the overlap rule. Actions keep their clip-relative fraction.
    ///
    /// On a RAMPED clip the whole rate profile scales by f = D ÷ (to_end −
    /// start) through `scaled_profile`, so the ramp keeps its shape and its
    /// window; an f that would take any rate the clip names past the limits
    /// (`profile_factors`) changes nothing (spec §11 SR-19 (a), (b)).
    /// Refused on a linked clip (spec §11 AU-94).
    pub fn rate_stretch(&self, clip: u32, to_end: Ticks) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        if !matches!(target.source, Source::Media { .. }) {
            return Err(format!("clip {clip} is not a media clip"));
        }
        let to_end = self.snapped(to_end);
        let duration = to_end.saturating_sub(target.start);
        if duration < self.frame() {
            return Ok(Outcome::Identity);
        }
        if let Some((low, high)) = profile_factors(&target) {
            let factor = target.duration as f64 / duration as f64;
            if !factor.is_finite() || !(low..=high).contains(&factor) {
                return Ok(Outcome::Identity);
            }
            let moved = self.scaled_profile(&target, factor, duration);
            return self.commit_rate(&target, moved);
        }
        let rate = self.content_length_in_source(&target) as f64 / duration as f64;
        if !rate.is_finite() || !(SPEED_MIN..=SPEED_MAX).contains(&rate) {
            return Ok(Outcome::Identity);
        }

        let mut moved = target.clone();
        moved.speed = rate;
        moved.duration = duration;
        self.rescale_actions(&mut moved.actions, target.duration, duration);
        self.commit_rate(&target, moved)
    }

    /// A rate edit's commit: refused on a linked clip whose rate it changes
    /// (spec §11 AU-94), else placed as any replacement is.
    fn commit_rate(&self, before: &Clip, moved: Clip) -> Result<Outcome, String> {
        if let Some(why) = self.linked_rate_refusal(before, &moved) {
            return Ok(Outcome::Refused(why));
        }
        self.commit_replacements(vec![moved])
    }

    /// Sets the clip's playback rate: `duration = source_len / rate` held
    /// to what the file holds AT THAT RATE (`duration_at_speed`, spec §11
    /// D4-3), actions keeping their clip-relative fraction (spec §6). Media
    /// sources only; `keep_pitch`, when given, sets the time-pitch flag.
    ///
    /// Takes a `rate` or a `duration`, exactly one (spec §11 #190). A
    /// duration is the Fit arm: snapped to the grid, held to a frame, and
    /// turned into the rate that plays the clip's content in it; the current
    /// duration keeps the current rate, so it makes no phantom step.
    ///
    /// Either rate is clamped to `SPEED_MIN`–`SPEED_MAX` rather than
    /// refused, because a slider or an MCP call that asks for more wants the
    /// fastest thing available. `Err` for both or neither, a non-media clip,
    /// a rate that is not a positive finite number or a duration that is not
    /// positive; refuses on an overlap-rule violation.
    ///
    /// On a RAMPED clip the whole rate profile scales by one factor f — the
    /// clamped rate over the base, or D ÷ d — clamped so no rate the clip
    /// names passes a limit (`profile_factors`): the ramp keeps its shape
    /// and its window, and its base may stop short of the rate asked; when
    /// f does not clamp, the base is the clamped rate itself. The
    /// new duration is d, or snapped(round(D ÷ f)) when f clamped or the
    /// rate arm set it, held through `scaled_profile` (spec §11 SR-19 (a),
    /// (b)). An f of 1 changes nothing but `keep_pitch`. A linked clip's
    /// rate is refused (spec §11 AU-94); `keep_pitch` alone is not a rate.
    pub fn set_speed(
        &self,
        clip: u32,
        rate: Option<f64>,
        duration: Option<Ticks>,
        keep_pitch: Option<bool>,
    ) -> Result<Outcome, String> {
        match (rate, duration) {
            (Some(_), Some(_)) => {
                return Err(format!(
                    "set_speed takes a rate or a duration, not both (clip {clip})"
                ))
            }
            (None, None) => {
                return Err(format!(
                    "set_speed takes a rate or a duration (clip {clip})"
                ))
            }
            _ => {}
        }
        let target = self.require_clip(clip)?.clone();
        if !matches!(target.source, Source::Media { .. }) {
            return Err(format!("clip {clip} is not a media clip"));
        }
        if let Some(rate) = rate {
            if !(rate.is_finite() && rate > 0.0) {
                return Err(format!("speed must be a positive number, not {rate}"));
            }
        }
        if let Some(duration) = duration {
            if duration <= 0 {
                return Err(format!("duration must be positive, not {duration}"));
            }
        }
        if let Some((low, high)) = profile_factors(&target) {
            let frame = self.frame();
            let (asked, fitted) = match (rate, duration) {
                (Some(rate), _) => (rate.clamp(SPEED_MIN, SPEED_MAX) / target.speed, None),
                (None, Some(duration)) => {
                    let d = self.snapped(duration).max(frame);
                    if d == target.duration {
                        (1.0, None)
                    } else {
                        (target.duration as f64 / d as f64, Some(d))
                    }
                }
                (None, None) => (1.0, None),
            };
            let factor = asked.clamp(low, high);
            let length = match fitted {
                Some(d) if factor == asked => d,
                _ => {
                    let scaled = (target.duration as f64 / factor).round();
                    if scaled.is_finite() {
                        self.snapped(scaled as Ticks).max(frame)
                    } else {
                        target.duration
                    }
                }
            };
            let mut moved = self.scaled_profile(&target, factor, length);
            // An unclamped rate arm writes the rate asked itself: `speed ×
            // (rate ÷ speed)` can miss it by an ULP (spec §11 SR-19 (a)).
            if let (Some(rate), true) = (rate, factor == asked) {
                moved.speed = rate.clamp(SPEED_MIN, SPEED_MAX);
            }
            if let (Some(keep), Some(audio)) = (keep_pitch, moved.audio.as_mut()) {
                audio.keep_pitch = keep;
            }
            return self.commit_rate(&target, moved);
        }
        let rate = match (rate, duration) {
            (Some(rate), _) => rate,
            (None, Some(duration)) => {
                let d = self.snapped(duration).max(self.frame());
                if d == target.duration {
                    target.speed
                } else {
                    self.content_length_in_source(&target) as f64 / d as f64
                }
            }
            (None, None) => target.speed,
        };
        let rate = rate.clamp(SPEED_MIN, SPEED_MAX);

        let mut moved = target.clone();
        moved.speed = rate;
        moved.duration = self.duration_at_speed(&target, rate);
        self.rescale_actions(&mut moved.actions, target.duration, moved.duration);
        if let (Some(keep), Some(audio)) = (keep_pitch, moved.audio.as_mut()) {
            audio.keep_pitch = keep;
        }
        self.commit_rate(&target, moved)
    }
}
import AppKit

/// The question a person is asked before a speed change takes a clip with
/// sound above the core's audio ceiling (#212, spec §11 #190's "The
/// question"), and the sentence an agent reads instead.
///
/// **A crossing is read off the core's answer, never predicted.** The ops are
/// applied to the immutable handle (the trial the Speed sheet's readout
/// already runs, spec §11 D4-6) and the two snapshots are compared: a clip
/// that plays at or below `audio_max` before and above it after, with its
/// audio enabled and media that has sound. No rate is computed here (D2-1),
/// and no Swift file types the ceiling — it is `ReelSpeed.limits.audioMax`.
///
/// A clip that is new in the answer (a split's half, a duplicate, a detach)
/// never counts, and one already above the ceiling is not asked about again.
/// A `retime_range` (Clip ▸ Retime Range…, spec §11 CU-90 (c)) is read on a
/// BASELINE instead of the project: the project with `split` at its `from`
/// and then its `to` applied, so a half the retime takes past the ceiling is
/// already in the "before" under the id the core will mint, and counts.
/// A clip's rate here is its PEAK (`peakSpeed`): a speed ramp (spec §11
/// SR-10) leaves the audio out when any rate it names is above the
/// ceiling, as the core's plan does (SR-19 (d)).
/// Nothing here is a refusal: Set Speed applies the edit exactly as it would
/// have been applied without the question.
enum SpeedAudioDrop {
    /// A clip the edit takes above the ceiling. `name` is the after
    /// snapshot's `name(of:)`; `speed` is the clip's NEW peak rate as the
    /// core answered it.
    struct Clip: Equatable {
