import collections
import glob
import json
import os
import re
import sys

W = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, W)
import speed_a
import speed_b

R = os.path.dirname(W) + '/'
OUT = R + 'features/speed.json'
REPO = '/Users/kevingalligan/devel/framejob/.claude/worktrees/help-docs/'
feats = speed_a.FEATURES + speed_b.FEATURES

recs = {}
for p in sorted(glob.glob(R + 'raw/*.json')):
    for r in json.load(open(p)):
        recs[r['id']] = r
tax = json.load(open(R + 'taxonomy.json'))
assign = json.load(open(R + 'tax/assign.json'))
section_of_page = {p['slug']: s['id'] for s in tax['sections'] for p in s['pages']}
pages = [p['slug'] for s in tax['sections'] if s['id'] == 'speed' for p in s['pages']]

AREA = {
    'text-shapes': 'text-and-shapes', 'transitions': 'motion', 'interface': 'getting-started',
    'media': 'projects', 'playback': 'timeline', 'settings': 'reference', 'transcript': 'cleanup',
    'mattes': 'effects', 'other': 'projects',
}
FORCE = {
    'guide-mcp-145': 'mcp', 'guide-mcp-158': 'mcp', 'guide-mcp-159': 'mcp', 'guide-mcp-160': 'mcp',
    'guide-mcp-161': 'mcp', 'guide-mcp-133': 'mcp', 'guide-speed-016': 'mcp',
    'guide-speed-048': 'mcp', 'guide-speed-093': 'mcp', 'guide-editing-045': 'mcp',
    'guide-menus-and-shortcuts-376': 'mcp', 'guide-menus-and-shortcuts-382': 'mcp',
    'guide-menus-and-shortcuts-383': 'mcp', 'guide-menus-and-shortcuts-407': 'mcp',
    'code-screens-482': 'mcp', 'code-screens-506': 'mcp', 'code-screens-536': 'mcp',
    'code-screens-551': 'mcp', 'code-screens-570': 'mcp', 'code-screens-574': 'mcp',
    'code-screens-582': 'mcp', 'guide-speed-062': 'editing', 'code-history-296': 'editing',
    'guide-speed-066': 'captions', 'guide-speed-119': 'audio', 'code-audio-153': 'audio',
    'code-core-ops-053': 'motion', 'guide-motion-and-transitions-152': 'motion',
}
RECORDING = re.compile(r'speed.up.typing|typing stretch|^shortcuts stay|^speech (and shortcuts )?stay|'
                       r'^clean edges$|^split recordings treated|^everything stays in step', re.I)

claimed = collections.Counter(i for f in feats for i in f['raw_ids'])


def section_for(r):
    if r['id'] in FORCE:
        return FORCE[r['id']]
    if r.get('area') == 'speed':
        if RECORDING.search(r['name']):
            return 'recording'
        return None
    # the taxonomy's own page for this name, when it is not one of ours
    name = r['name'].lower()
    for page, names in assign.items():
        if name in names and not page.startswith('speed/'):
            return section_of_page.get(page)
    area = r.get('area')
    return AREA.get(area, area)


# what a search for this section's words finds by name, UI or tool, and what
# the taxonomy pointed at this section by name
kw = re.compile(r'(\bspeed|\bramp|retime|varispeed|rate.stretch|keep.pitch|preserve.pitch|freeze|'
                r'\breverse|reversing|set_speed|fit.to|\bfit to\b)', re.I)
candidates = set()
for r in recs.values():
    head = ' '.join([r.get('name', '')] + (r.get('ui') or []) + (r.get('mcp') or []))
    if r.get('area') == 'speed' or r['id'].startswith('guide-speed') or kw.search(head):
        candidates.add(r['id'])
by_name = collections.defaultdict(list)
for r in recs.values():
    by_name[r['name'].lower()].append(r['id'])
for page, names in assign.items():
    if page.startswith('speed/'):
        for n in names:
            candidates.update(by_name.get(n, []))

rejected = []
orphans = []
for i in sorted(candidates):
    if i in claimed:
        continue
    sec = section_for(recs[i])
    if sec is None or sec == 'speed':
        orphans.append(i)
        continue
    rejected.append({'raw_id': i, 'reason': 'belongs to ' + sec})

doc = {'section': 'speed', 'features': feats, 'rejected': rejected}
os.makedirs(os.path.dirname(OUT), exist_ok=True)
json.dump(doc, open(OUT, 'w'), ensure_ascii=False, indent=1)

# ---- checks
problems = []
ids = collections.Counter(f['id'] for f in feats)
problems += ['dup id ' + k for k, v in ids.items() if v > 1]
problems += ['dup claim ' + k for k, v in claimed.items() if v > 1]
problems += ['unknown raw ' + k for k in claimed if k not in recs]
problems += ['orphan ' + k for k in orphans]
anchors = collections.Counter((f['page'], f['anchor']) for f in feats)
problems += ['dup anchor %s' % (k,) for k, v in anchors.items() if v > 1]
for f in feats:
    if f['page'] not in pages:
        problems.append('bad page ' + f['id'])
    for ref in f['code_refs']:
        path, _, line = ref.partition(':')
        if not os.path.exists(REPO + path):
            problems.append('missing file ' + ref)
        elif line:
            n = sum(1 for _ in open(REPO + path, errors='replace'))
            if int(line) > n:
                problems.append('line past end ' + ref)
    if not f['summary'].endswith('.'):
        problems.append('summary stop ' + f['id'])
    for t in f['mcp']:
        if ' ' in t:
            problems.append('mcp form %s %s' % (f['id'], t))
unclaimed_area = [i for i, r in recs.items() if r.get('area') == 'speed'
                  and i not in claimed and i not in {x['raw_id'] for x in rejected}]
problems += ['unhandled area ' + i for i in unclaimed_area]
banned = re.compile(r'\b(spec|road ?map|phase|§|rc_|the core|op table|proof)\b', re.I)
for f in feats:
    for s in [f['summary'], f['name']] + f['details']:
        m = banned.search(s)
        if m:
            problems.append('word %s in %s: %s' % (m.group(0), f['id'], s[:60]))
print('features', len(feats), 'claimed', len(claimed), 'rejected', len(rejected))
print(collections.Counter(f['page'] for f in feats))
print('empty pages', [p for p in pages if not any(f['page'] == p for f in feats)])
print(collections.Counter(x['reason'] for x in rejected))
print('PROBLEMS', len(problems))
for p in problems:
    print(' ', p)

